// Free times for the next days, from the opening hours in Settings minus the bookings.
const s = $('Settings').first().json;
const zone = s.timezone;
const now = DateTime.now().setZone(zone);
const earliest = now.plus({ minutes: s.minimumNoticeMinutes });
const booked = new Set($input.all().map((i) => i.json.start).filter(Boolean));
const days = String(s.openDays).split(',').map((d) => Number(d.trim()));
const [openH, openM] = s.opensAt.split(':').map(Number);
const [closeH, closeM] = s.closesAt.split(':').map(Number);

const free = [];
const lines = [];
for (let d = 0; d < s.daysAhead; d++) {
  const day = now.startOf('day').plus({ days: d });
  if (!days.includes(day.weekday)) continue;
  const times = [];
  let t = day.set({ hour: openH, minute: openM });
  const close = day.set({ hour: closeH, minute: closeM });
  while (t.plus({ minutes: s.appointmentMinutes }) <= close) {
    const start = t.toFormat('yyyy-MM-dd HH:mm');
    if (t >= earliest && !booked.has(start)) { free.push(start); times.push(t.toFormat('HH:mm')); }
    t = t.plus({ minutes: s.appointmentMinutes });
  }
  if (times.length) lines.push(day.toFormat('cccc d LLLL yyyy') + ' (' + day.toFormat('yyyy-MM-dd') + '): ' + times.join(', '));
}

// What this visitor has already booked, so the agent can tell them.
const sessionId = $('When chat message received').first().json.sessionId;
const mine = $input.all().filter((i) => i.json.sessionId === sessionId && i.json.start).map((i) => i.json.start);

return [{ json: {
  sessionId,
  chatInput: $('When chat message received').first().json.chatInput,
  today: now.toFormat('cccc d LLLL yyyy, HH:mm'),
  freeTimes: lines.join('\n') || 'No free time in the coming days.',
  free,
  alreadyBooked: mine.join(', '),
} }];

const out = $input.first().json;
const steps = out.intermediateSteps ?? [];
const call = steps.filter((s) => s.action?.tool === 'Request_a_booking').pop();
const free = $('Free times').first().json.free;
const sessionId = $('Free times').first().json.sessionId;
// richCards: where the business is and when it opens, drawn as a card when the agent looked it up.
const settings = $('Settings').first().json;
let output = out.output;
if (settings.richCards && steps.some((s) => s.action?.tool === 'Find_us')) {
  const [opens, closes] = [settings.opensAt, settings.closesAt];
  output += '\n\n\u0060\u0060\u0060card-place\n' + JSON.stringify({
    name: settings.businessName, address: settings.address, phone: settings.phone,
    ...(settings.latitude && settings.longitude ? { coordinates: { lat: settings.latitude, lng: settings.longitude } } : {}),
    hours: String(settings.openDays).split(',').map((d) => ({ day: Number(d.trim()), open: opens, close: closes })),
    utcOffset: DateTime.now().setZone(settings.timezone).offset,
  }) + '\n\u0060\u0060\u0060';
}
// The days or times the agent just offered, as quick replies to click (a suggestions block):
// only when no booking waits for its buttons, which are the answer then.
const offered = steps.filter((s) => s.action?.tool === 'Suggest_replies').pop();
const replies = [].concat(offered?.action?.toolInput?.replies ?? []).map((r) => String(r).trim()).filter(Boolean).slice(0, 4);
if (!call && settings.richCards && replies.length) {
  output += '\n\n\u0060\u0060\u0060suggestions\n' + JSON.stringify(replies) + '\n\u0060\u0060\u0060';
}
if (!call) return [{ json: { sessionId, asked: false, output } }];
const r = call.action.toolInput ?? {};
const start = String(r.start ?? '').trim();
const name = String(r.name ?? '').trim();
const email = String(r.email ?? '').trim();
let problem = '';
if (!free.includes(start)) problem = start + ' is not one of the free times. Please choose another time.';
else if (!name) problem = 'I need your name to book.';
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) problem = 'I need a valid email address to book.';
const when = DateTime.fromFormat(start, 'yyyy-MM-dd HH:mm', { zone: $('Settings').first().json.timezone });
return [{ json: {
  sessionId, asked: true, ok: !problem, problem, output,
  start, name, email,
  when: when.isValid ? when.toFormat('cccc d LLLL') + ' at ' + when.toFormat('HH:mm') : start,
} }];
